"""Turn disjoint ear-triple packing bounds into total ear-face count bounds."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1]
def bound(B,p):
 # Conflict edges connect tips two cyclic steps apart. Odd full parity cycle is the only deficit from >=E/2 packing.
 if B%4==2 and p>=(B-2)//4:return B//2
 return min(B//2,2*p)
def main():
 path=R/'verify/out/n100-disjoint-ear-group-cuts.json';ip=R/'verify/out/n100-disjoint-ear-group-cuts-independent.json';z=json.loads(path.read_text(encoding='utf-8'));a=json.loads(ip.read_text(encoding='utf-8'));assert a['input_sha256']==hashlib.sha256(path.read_bytes()).hexdigest();rows=[]
 for row in z['family_rows']:
  m,B,p=row['m'],row['B'],row['maximum_disjoint_three_site_ear_groups'];Emax=bound(B,p);rows.append({'m':m,'B':B,'maximum_disjoint_ear_triples':p,'maximum_total_ear_faces':Emax,'minimum_distinct_boundary_incident_faces':B-Emax,'triangle_face_counts_for_actual_ear_count_e':{'F2':'e','F1':f'{B}-2*e','F0':f'{2*m-2*B-2}+e'},'exceptional_alternating_odd_cycle_allowed_by_p':B%4==2 and p>=(B-2)//4})
 out=R/'verify/out/n100-total-ear-face-cuts.json';assert not out.exists();out.write_text(json.dumps({'schema':'n100-total-ear-face-cuts/v1','radius_upper_inclusive':z['radius_upper_inclusive'],'family_rows':rows,'analytic_combinatorial_proof':['in a triangulated disk with interior vertices and simple boundary cycle, a two-boundary-edge triangle is an ear at its degree2 boundary tip; adjacent ear tips would force incompatible diagonals (or whole triangular disk), so adjacent tips cannot occur','ear triples are tips together with predecessor/successor; for nonadjacent tips their triples overlap exactly at cyclic distance2','conflict graph of all ear tips is an induced subgraph of step2 graph on boundary indices, degree<=2; connected components are paths or full step2 cycles','a path or even cycle admits an independent set of size at least half its vertices, corresponding to pairwise disjoint ear triples','if B odd, a full step2 cycle uses all boundary indices and violates nonadjacency; if B divisible4, both full parity cycles are even','only B=2 mod4 allows an odd full parity cycle of length B/2; that forces all ears to one full parity class, no other tips, packing size(B-2)/4','hence total ears<=2p unless B=2 mod4 and p>=(B-2)/4, when trivial nonadjacency ceiling B/2 applies','if actual ears=e, boundary edge incidence gives F1+2e=B, Euler F=2m-B-2 gives F0=2m-2B-2+e; all boundary incident faces total B-e'],'scope':'uniform necessary total ear counts on17normalized families, inherited geometric packing premises; combinatorial proof analytic, finite formula/table checked, no full family exclusion','global_optimality':False,'input_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2)+'\n',encoding='utf-8');print('PASS total ear limits',[(r['m'],r['B'],r['maximum_total_ear_faces']) for r in rows])
if __name__=='__main__':main()
